css:
.d-back{position:relative;width:300px;height:150px;color:var(--ink)}
.d-back-screen{position:absolute;left:20px;top:14px;width:260px;height:104px;border:1px solid var(--line);border-radius:10px;background:var(--bg);overflow:hidden}
.d-back-under{position:absolute;inset:0;display:grid;place-items:center;font-family:var(--mono);font-size:11px;letter-spacing:.08em;color:var(--faint)}
.d-back-edge{position:absolute;left:0;top:0;bottom:0;width:18px;z-index:2;cursor:ew-resize;touch-action:none}
.d-back-grip{position:absolute;left:7px;top:50%;width:1px;height:24px;margin-top:-12px;background:var(--line)}
.d-back-edge:focus-visible{outline:1px solid var(--ink);outline-offset:-2px}
.d-back-page{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:flex-end;gap:4px;padding:10px 12px;background:var(--paper);border-left:1px solid var(--line);border-radius:10px;box-shadow:0 1px 0 var(--line);will-change:transform}
.d-back-page b{font-size:13px;font-weight:650}
.d-back-page em{font-style:normal;font-family:var(--mono);font-size:9px;letter-spacing:.04em;color:var(--faint)}
.d-back-ruler{position:absolute;left:20px;top:130px;width:260px;height:1px;background:var(--line)}
.d-back-fill{position:absolute;left:0;top:0;width:0;height:1px;background:#c2402a}
.d-back-tick{position:absolute;left:30%;top:-2px;width:1px;height:5px;background:var(--ink)}
.d-back-hint{position:absolute;left:20px;top:136px;margin:0;font-family:var(--mono);font-size:9px;line-height:1.6;color:var(--faint)}

init:
root => {
  const box = root.querySelector('.d-back');
  if (!box || box.dataset.ready) return;
  box.dataset.ready = '1';
  const page = box.querySelector('.d-back-page');
  const edge = box.querySelector('.d-back-edge');
  const fill = box.querySelector('.d-back-fill');
  const under = box.querySelector('.d-back-under');
  const hint = box.querySelector('.d-back-hint');
  const W = 260;
  const IDLE = '过 30% 才提交 · 30% 处有刻度';
  let x = 0, drag = null;

  function draw() {
    page.style.transform = 'translateX(' + x.toFixed(1) + 'px)';
    fill.style.width = Math.min(100, (x / W) * 100).toFixed(1) + '%';
  }
  function commit() {
    page.style.transition = 'transform .28s cubic-bezier(.34,1.56,.64,1)';
    x = W;
    draw();
    under.textContent = '已返回';
    hint.textContent = '已返回上一页 · 260px 一次走完';
    clearTimeout(box._t);
    box._t = setTimeout(() => {
      page.style.transition = 'none';
      x = 0;
      draw();
      under.textContent = '← 上一页';
      hint.textContent = IDLE;
    }, 280);
  }
  function reset() {
    page.style.transition = 'transform .28s cubic-bezier(.34,1.56,.64,1)';
    x = 0;
    draw();
    hint.textContent = IDLE;
  }
  function down(e) {
    if (drag) return;
    e.preventDefault();
    edge.focus({ preventScroll: true });
    edge.setPointerCapture(e.pointerId);
    page.style.transition = 'none';
    drag = { x0: e.clientX };
    x = 0;
    draw();
  }
  function move(e) {
    if (!drag) return;
    let dx = e.clientX - drag.x0;
    if (dx < 0) dx = dx * .2;
    x = Math.min(W, dx);
    draw();
    hint.textContent = x / W >= .3 ? '过 30% · 松手就返回' : '还差 ' + Math.round((.3 - x / W) * 100) + '% 才提交';
  }
  function up() {
    if (!drag) return;
    drag = null;
    if (x / W >= .3) commit(); else reset();
  }
  function key(e) {
    if (e.key === 'ArrowRight') { e.preventDefault(); commit(); }
    else if (e.key === 'ArrowLeft' || e.key === 'Escape') { e.preventDefault(); reset(); }
  }

  edge.addEventListener('pointerdown', down);
  edge.addEventListener('pointermove', move);
  edge.addEventListener('pointerup', up);
  edge.addEventListener('pointercancel', up);
  edge.addEventListener('keydown', key);
  draw();
}
